// ============================================
// VALIDATE CALLBACK INPUT (batch multi)
// ============================================

const input = $input.first().json;
const body = input.body || input;

// --- defensive parse: metadata may arrive as a JSON string ---
let md = body.metadata;
if (typeof md === 'string') {
  try { md = JSON.parse(md); } catch (e) { md = {}; }
}
md = md || {};

// --- defensive parse: results may arrive as a JSON string ---
let results = body.results;
if (typeof results === 'string') {
  try { results = JSON.parse(results); } catch (e) { results = []; }
}
results = Array.isArray(results) ? results : [];

const errors = [];
if (results.length === 0) errors.push('results');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    message: 'Missing required fields: ' + errors.join(', ')
  };
}

return {
  valid: true,
  data: {
    batch_id: body.batch_id || null,
    correlation_id: body.correlation_id || null,
    results: results,
    metadata: md,
    job_id: md.job_id || null,
    project_id: md.project_id || null,
    channel_id: md.callback_channel_id || null,
    target_lang: md.target_lang || null,
    // Provenance posee par le dispatcher : /save-batch les accepte tous trois
    // en optionnel, mais sans eux la ligne ecrite ne dit ni sa langue ni son
    // origine. Aucune valeur de repli inventee ici : un modele faux est pire
    // qu'un modele absent (azy.daily#201).
    // Appairage azy.daily#225, posé par le dispatcher et ré-échoté par le poller.
    correlation_id: body.correlation_id || md.correlation_id || null,
    client_metadata: md.client_metadata || null,
    target_language: md.target_language || null,
    provider: md.provider || null,
    model: md.model || null,
    commentary_map: md.commentary_map || {}
  }
};

// ============================================
// SPLIT RESULTS — un item n8n par résultat de traduction
// ============================================

const data = $input.first().json.data;
const map = data.commentary_map || {};

return (data.results || []).map((r, i) => ({ json: {
  rang: i,                         // ordre stable : sert à recoller les résultats de /save-batch
  job_id: data.job_id,
  project_id: data.project_id,
  channel_id: data.channel_id,
  correlation_id: data.correlation_id,
  client_metadata: data.client_metadata,
  // La carte dit la NATURE de l'item : le custom_id porte soit un commentary_id
  // soit un segment_id, et un seul des deux doit ressortir — /api/translations/save
  // refuse le couple (contrat azy.daily#201). Auparavant tout custom_id atterrissait
  // dans commentary_id, ce qui envoyait les versets dans la mauvaise table.
  commentary_id: (map[r.custom_id] || {}).commentary_id || null,
  segment_id: (map[r.custom_id] || {}).segment_id || null,
  // Provenance, transmise telle quelle à /save-batch quand elle est connue.
  target_language: data.target_language || null,
  provider: data.provider || null,
  model: data.model || null,
  ok: r.ok === true,
  translated_text: r.ok ? r.text : null,
  error: r.ok ? null : r.error
}}));

// ============================================
// AGGREGATE RESULTS — un item de synthèse pour le job et Discord
// ============================================

const items = $input.all().map(i => i.json);

let okCount = 0;
let failCount = 0;
const echecs = [];

items.forEach(it => {
  // save_ok vaut null quand la traduction elle-même a échoué : l'item n'a jamais
  // été proposé à l'écriture, et le compter en échec de sauvegarde effacerait la
  // vraie cause.
  const traductionOk = it.ok === true;
  const sauvegardeOk = traductionOk ? it.save_ok === true : false;
  if (traductionOk && sauvegardeOk) {
    okCount++;
  } else {
    failCount++;
    if (echecs.length < 20) {
      echecs.push({
        rang: it.rang,
        cause: traductionOk ? 'sauvegarde' : 'traduction',
        detail: traductionOk ? it.save_error : it.error
      });
    }
  }
});

const first = items[0] || {};

return {
  job_id: first.job_id || null,
  correlation_id: first.correlation_id || null,
  client_metadata: first.client_metadata || null,
  project_id: first.project_id || null,
  channel_id: first.channel_id || null,
  total: items.length,
  ok_count: okCount,
  fail_count: failCount,
  // Vingt premiers échecs : de quoi retraiter chirurgicalement sans gonfler le job.
  echecs: echecs
};

// ============================================
// PREPARE DISCORD NOTIFICATION (batch)
// ============================================

const agg = $('Aggregate Results').first().json;

const message = `✅ Traduction terminée (${agg.ok_count} ok / ${agg.fail_count} erreurs)`;

return {
  channel_id: agg.channel_id,
  job_id: agg.job_id,
  ok_count: agg.ok_count,
  fail_count: agg.fail_count,
  message: message
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const discordResult = $input.first().json;
const msgData = $('Prepare Discord').first().json;

return {
  success: true,
  job_id: msgData.job_id,
  ok_count: msgData.ok_count,
  fail_count: msgData.fail_count,
  notification_sent: discordResult.id ? true : false,
  message: 'Callback processed successfully'
};

// ============================================
// FORMAT NO CHANNEL RESPONSE
// ============================================

const msgData = $input.first().json;

return {
  success: true,
  job_id: msgData.job_id,
  ok_count: msgData.ok_count,
  fail_count: msgData.fail_count,
  notification_sent: false,
  message: 'Callback processed (no channel to notify)'
};

// ============================================
// FORMAT VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.message || 'Invalid callback data',
    http_status: 400
  }
};

// ============================================
// GROUPER SAUVEGARDES — un lot par appel à /api/translations/save-batch
// ============================================
//
// Remplace N appels à /api/translations/save par ⌈N/500⌉ appels groupés.
// Mesuré sur 250 items : ~350 s en unitaire (au-delà du timeout, azy.daily#201),
// ~6,5 s en groupé.
//
// Pourquoi 500 et non 2 500 (le maximum accepté par l'API)
// -------------------------------------------------------
// Le timeout d'un nœud HTTP Request n8n couvre l'ENSEMBLE des items, pas chaque
// appel : c'est exactement ce qui a fait échouer la version unitaire. Des lots
// bornés gardent chaque requête autour de 13 s (26 ms/item mesurés par l'API),
// laissent de la marge sous le timeout du nœud même dans le pire cas connu
// (2 498 items d'une aliyah sans filtre → 5 lots), et isolent une défaillance
// réseau sur un cinquième du travail au lieu de la totalité.
//
// Ce nœud émet TOUJOURS au moins un item : sans cela, un lot dont aucune
// traduction n'a abouti court-circuiterait tout l'aval — pas de mise à jour du
// job, pas de notification. L'item sentinelle porte aucun_envoi: true.

const TAILLE_LOT = 500;

const tous = $input.all().map(i => i.json);
const premier = tous[0] || {};

// Seules les traductions réussies sont écrites. Les échecs sont comptés en aval.
const aEcrire = tous.filter(it => it.ok === true && it.translated_text);

if (aEcrire.length === 0) {
  return [{ json: {
    aucun_envoi: true,
    job_id: premier.job_id || null,
    total: tous.length
  }}];
}

const lots = [];
for (let d = 0; d < aEcrire.length; d += TAILLE_LOT) {
  const tranche = aEcrire.slice(d, d + TAILLE_LOT);
  lots.push({ json: {
    aucun_envoi: false,
    lot_index: lots.length,
    rangs: tranche.map(it => it.rang),   // recollage : /save-batch répond par index
    items: tranche.map(it => {
      // Exactement un identifiant, jamais les deux : l'API refuse le couple.
      const item = it.commentary_id
        ? { commentary_id: it.commentary_id }
        : { segment_id: it.segment_id };
      item.translated_text = it.translated_text;
      // Champs optionnels : omis plutôt que remplis d'une valeur inventée.
      if (it.target_language) item.target_language = it.target_language;
      if (it.provider) item.provider = it.provider;
      if (it.model) item.model = it.model;
      return item;
    })
  }});
}

return lots;

// ============================================
// ÉCLATER SAUVEGARDES — recoller le sort de chaque traduction
// ============================================
//
// /api/translations/save-batch répond 200 même quand des items échouent, et
// isole le détail dans per_item_results[i] avec l'index d'entrée. On remonte
// donc ce verdict sur chaque traduction, au lieu de conclure du seul code HTTP.
//
// La source de vérité reste $('Split Results') : ce nœud rend une ligne par
// traduction reçue d'Anthropic, y compris celles jamais envoyées à l'écriture
// (traduction en échec, ou aucun envoi du tout). L'agrégat en aval compte sur
// ce total.

const traductions = $('Split Results').all().map(i => i.json);

// Verdict par rang, alimenté par les réponses de chaque lot.
const verdicts = {};

// Appariement par POSITION, pas par contenu : la réponse HTTP ne rapporte rien
// du lot qui l'a produite. Le nœud HTTP émet un item de sortie par item d'entrée
// et dans le même ordre, donc entrees[i] correspond au lot i. C'est le seul
// point du workflow où l'ordre porte du sens — d'où le rang stable posé par
// Split Results, qui rend le recollage vérifiable en aval.
const entrees = $input.all();
const lots = $('Grouper Sauvegardes').all();

for (let i = 0; i < entrees.length; i++) {
  const j = entrees[i].json;
  if (j.aucun_envoi) continue;                 // branche « rien à écrire »

  // Avec onError=continueRegularOutput, un appel en échec n'émet pas
  // {statusCode, body} : le statut réel est enfoui dans le message (« 500 - {…} »).
  // Sans cette lecture, un lot entièrement perdu passerait pour sauvegardé.
  let code = j.statusCode;
  if (code === undefined) {
    const brut = String(j?.error?.message || j?.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    code = m ? parseInt(m[1], 10) : ((j?.error || j?.code) ? 502 : 200);
  }
  const corps = j.body || {};

  const rangs = ((lots[i] || {}).json || {}).rangs || [];

  if (code >= 400 || !Array.isArray(corps.per_item_results)) {
    const motif = code >= 400
      ? ('save-batch HTTP ' + code)
      : 'save-batch : réponse sans per_item_results';
    rangs.forEach(r => { verdicts[r] = { save_ok: false, save_error: motif }; });
    continue;
  }

  corps.per_item_results.forEach(res => {
    const rang = rangs[res.index];
    if (rang === undefined) return;
    verdicts[rang] = res.success
      ? { save_ok: true, save_error: null }
      : { save_ok: false,
          save_error: (res.error && (res.error.detail || res.error.status_code)) || 'échec sauvegarde' };
  });
}

return traductions.map(t => {
  const v = verdicts[t.rang];
  return { json: Object.assign({}, t, {
    // Une traduction en échec n'a jamais été proposée à l'écriture : elle ne doit
    // pas être comptée comme un échec de sauvegarde, sinon la cause se perd.
    save_ok: t.ok === true ? (v ? v.save_ok : false) : null,
    save_error: t.ok === true ? (v ? v.save_error : 'jamais soumise à la sauvegarde') : null
  })};
});

// ============================================
// PRÉPARER ÉVÉNEMENT — branche latérale, azy.daily#225
// ============================================
//
// Émis APRÈS /save-batch : c'est le seul point de la chaîne qui sache ce qui a
// RÉELLEMENT été écrit. Le Batch Poller publie lui aussi, mais en parallèle du
// callback — donc avant l'écriture. Un événement venu de lui aurait fait annoncer
// « prête » et débiter sur des traductions non persistées.
//
// Branche LATÉRALE : elle ne réinjecte rien dans le chemin principal, qui garde
// donc exactement son comportement (mise à jour du job, notification Discord).
//
// Retourner un tableau VIDE arrête la branche : aucun appel Redis, aucun effet.
// C'est ce qui rend le mécanisme inoffensif pour les appelants qui n'ont rien
// demandé — et ils sont tous dans ce cas aujourd'hui.

const agg = $input.first().json;

if (!agg.correlation_id) {
  return [];
}

// Les champs d'un stream Redis sont des chaînes : les objets sont encodés, et le
// consommateur relira des chaînes même pour les compteurs.
return [{ json: {
  stream: 'llm:results:stream',
  fields: {
    event: 'translation_complete',
    correlation_id: agg.correlation_id,
    success: String(agg.ok_count > 0),
    job_id: agg.job_id || '',
    total: String(agg.total),
    ok_count: String(agg.ok_count),
    fail_count: String(agg.fail_count),
    echecs: JSON.stringify(agg.echecs || []),
    metadata: JSON.stringify(agg.client_metadata || {}),
    error_code: agg.fail_count === agg.total && agg.total > 0 ? 'ALL_FAILED' : '',
    error_message: agg.fail_count > 0 ? (agg.fail_count + ' item(s) en erreur') : '',
    completed_at: new Date().toISOString()
  },
  max_len: 5000
}}];
